import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { greet } from '../bin/greet.mjs';

const cliPath = fileURLToPath(new URL('../bin/greet.mjs', import.meta.url));

test('greets the world by default', () => {
  assert.equal(greet(), 'Hello, world!');
});

test('greets a name', () => {
  assert.equal(greet('Mike'), 'Hello, Mike!');
});

const cases = [
  { args: [], expected: 'Hello, world!\n' },
  { args: ['Mike'], expected: 'Hello, Mike!\n' },
  { args: ['--shout'], expected: 'HELLO, WORLD!\n' },
  { args: ['--shout', 'Mike'], expected: 'HELLO, MIKE!\n' },
  { args: ['Mike', '--shout'], expected: 'HELLO, MIKE!\n' },
];

for (const { args, expected } of cases) {
  test(`CLI greets with ${args.join(' ') || 'no arguments'}`, () => {
    const output = execFileSync(process.execPath, [cliPath, ...args], {
      encoding: 'utf8',
    });
    assert.equal(output, expected);
  });
}

#!/usr/bin/env node
// greet: prints a friendly greeting.
// Usage: greet [--shout] [name]
export function greet(name = 'world') {
  return `Hello, ${name}!`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const args = process.argv.slice(2);
  const shout = args.includes('--shout');
  const name = args.find((arg) => arg !== '--shout');
  const greeting = greet(name);
  console.log(shout ? greeting.toUpperCase() : greeting);
}
